def gen(rng):
    def fmt(a, k):
        return str(len(a)) + '\n' + ' '.join(map(str, a)) + '\n' + str(k)
    tests = [fmt([7], 0), fmt([7], 5), fmt([1, 2], 1), fmt([1, 2, 3], 3), fmt([1, 2, 3], 0), fmt([5, 5, 5, 6], 2), fmt([-3, 0, 4], 4)]
    for n in (2, 3, 4, 5, 7, 10, 15, 20):
        for _ in range(2):
            a = [rng.randint(-50, 50) for _ in range(n)]
            tests.append(fmt(a, rng.randint(0, 3 * n)))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], 10**9))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], N * 7 + 12345))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)], N - 1))
    tests.append(fmt(list(range(N)), 10**9 - 1))
    return tests

